tool_input.command:
node -e "
const parse = require('./src/parse.js').parse;

// Test cases
const tests = [
  { input: '2024-01-15', desc: 'ISO date' },
  { input: '2024-01-15T10:30:00Z', desc: 'ISO datetime' },
  { input: 'Mon Sep 22 2026', desc: 'text format' },
  { input: '1234567890000', desc: 'timestamp' }
];

console.log('Testing date parser:');
tests.forEach(test => {
  try {
    const result = parse(test.input);
    if (isNaN(result.getTime())) {
      console.log(\`❌ \${test.desc}: returned invalid date\`);
    } else {
      console.log(\`✓ \${test.desc}: \${result.toISOString()}\`);
    }
  } catch (e) {
    console.log(\`❌ \${test.desc}: \${e.message}\`);
  }
});
"

node << 'EOF'
const parse = require('./src/parse.js').parse;

// Test cases
const tests = [
  { input: '2024-01-15', desc: 'ISO date' },
  { input: '2024-01-15T10:30:00Z', desc: 'ISO datetime' },
  { input: 'Mon Sep 22 2026', desc: 'text format' },
  { input: '1234567890000', desc: 'timestamp' }
];

console.log('Testing date parser:');
tests.forEach(test => {
  try {
    const result = parse(test.input);
    if (isNaN(result.getTime())) {
      console.log(`❌ ${test.desc}: returned invalid date`);
    } else {
      console.log(`✓ ${test.desc}: ${result.toISOString()}`);
    }
  } catch (e) {
    console.log(`❌ ${test.desc}: ${e.message}`);
  }
});
EOF
